// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: Draft switcher in the project header – a button opening a popover with links to the project and its
//          open drafts (label, last change, "updated by agent" as text). Links, not menu items: every entry
//          navigates (Tab moves through them, Esc / click outside closes, the browser manages aria-expanded).

import { Link } from '@tanstack/react-router'
import { useId, useRef } from 'react'
import { draftCount, updatedByAgent } from '#/lib/drafts'
import type { DraftSummary } from '#/server/projects.server'
import { formatTime } from './HistoryTab'

/** Active only on an exact search match (the router otherwise treats the project link as active inside a draft). */
export const EXACT_SEARCH = { exact: true, explicitUndefined: true } as const

export function DraftSwitcher({ drafts, current }: { drafts: DraftSummary[]; current: string | null }) {
  const popoverId = useId()
  const popover = useRef<HTMLDivElement>(null)
  // The draft being viewed is never "new" (viewing it records it as seen).
  const fresh = drafts.filter((d) => d.id !== current && updatedByAgent(d)).length
  // Nothing to switch to in a project without drafts.
  if (!drafts.length && !current) return null
  const close = () => popover.current?.hidePopover()

  return (
    <div className="draft-switcher">
      <button
        type="button"
        popoverTarget={popoverId}
        className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/5 px-3 py-1.5 text-sm text-zinc-200 transition hover:border-white/25 hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400 aria-expanded:border-indigo-400/60"
      >
        Návrhy
        <span className="rounded-full bg-white/10 px-1.5 text-xs tabular-nums">{drafts.length}</span>
        {fresh > 0 && (
          <span className="rounded-full bg-amber-400/15 px-1.5 text-xs text-amber-200">
            {fresh} {fresh === 1 ? 'nový' : 'nové'}
            <span className="sr-only"> od agenta</span>
          </span>
        )}
        <span aria-hidden="true" className="text-xs text-zinc-400">
          ▾
        </span>
      </button>
      <div ref={popover} id={popoverId} popover="auto" className="draft-popover">
        <nav aria-label="Projekt a jeho návrhy">
          <ul className="flex flex-col gap-0.5">
            <li>
              <Link
                from="/p/$projectId"
                to="."
                search={(prev) => ({ ...prev, draft: undefined })}
                aria-current={current === null ? 'page' : undefined}
                activeOptions={EXACT_SEARCH}
                onClick={close}
                className="draft-link"
              >
                <span className="font-medium">Projekt</span>
                <span className="text-xs text-zinc-400">hlavná verzia</span>
              </Link>
            </li>
            {drafts.map((d) => {
              const isNew = d.id !== current && updatedByAgent(d)
              return (
                <li key={d.id}>
                  <Link
                    from="/p/$projectId"
                    to="."
                    search={(prev) => ({ ...prev, draft: d.id })}
                    aria-current={d.id === current ? 'page' : undefined}
                    activeOptions={EXACT_SEARCH}
                onClick={close}
                    className="draft-link"
                  >
                    <span className="flex flex-wrap items-center gap-x-2">
                      <span className="font-medium [overflow-wrap:anywhere]">{d.label}</span>
                      {isNew && (
                        <span className="rounded-full bg-amber-400/15 px-1.5 text-[11px] text-amber-200">
                          <span aria-hidden="true">● </span>aktualizoval agent
                        </span>
                      )}
                    </span>
                    <span className="text-xs text-zinc-400">
                      Zmenené {formatTime(d.updatedAt)} · {d.lastChangedBy === 'agent' ? 'agent' : 'ty'}
                    </span>
                  </Link>
                </li>
              )
            })}
          </ul>
          <p className="mt-2 px-2 text-[11px] text-zinc-500">Otvorené: {draftCount(drafts.length)}</p>
        </nav>
      </div>
    </div>
  )
}
